/* @lc app=leetcode id=3737 lang=kotlin */ class Solution { fun countMajoritySubarrays(nums: IntArray, target: Int): Int = nums.size.let { n -> IntArray(2 * n + 3).also { it[n + 1] = 1 }.let { cnt -> nums.fold(Triple(n + 1, 0L, 0L)) { (p, less, ans), x -> (if (x == target) p + 1 else p - 1).let { np -> (if (x == target) less + cnt[p] else less - cnt[np]).let { nl -> cnt.set(np, cnt[np] + 1).let { Triple(np, nl, ans + nl) } } } }.third.toInt() } } }